INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('de69e945-bb01-4c62-a916-1420b2aaddac', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'definition', 'Keystone OS, en une phrase', '{"term":"Keystone OS","definition":"Keystone (Keystone OS) est un espace de travail modulaire édité par Protein Studio : il réunit des outils métier dans une seule application web installable (PWA), l''utilisateur active uniquement ce dont il a besoin via le K-Store, l''IA est incluse dans l''abonnement (compteur mensuel, pas de jetons), conçu local d''abord et souverain (données métier dans le navigateur, RGPD). IMPORTANT : Keystone n''est PAS un logiciel d''immobilier ni d''un métier unique — c''est un OS d''outils métier, généraliste et modulaire."}', 'Keystone OS, en une phrase
Keystone OS
Keystone (Keystone OS) est un espace de travail modulaire édité par Protein Studio : il réunit des outils métier dans une seule application web installable (PWA), l''utilisateur active uniquement ce dont il a besoin via le K-Store, l''IA est incluse dans l''abonnement (compteur mensuel, pas de jetons), conçu local d''abord et souverain (données métier dans le navigateur, RGPD). IMPORTANT : Keystone n''est PAS un logiciel d''immobilier ni d''un métier unique — c''est un OS d''outils métier, généraliste et modulaire.', 'validated', 'import', 'apps:keystone-os', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('de69e945-bb01-4c62-a916-1420b2aaddac', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Keystone OS, en une phrase', 'Keystone OS, en une phrase
Keystone OS
Keystone (Keystone OS) est un espace de travail modulaire édité par Protein Studio : il réunit des outils métier dans une seule application web installable (PWA), l''utilisateur active uniquement ce dont il a besoin via le K-Store, l''IA est incluse dans l''abonnement (compteur mensuel, pas de jetons), conçu local d''abord et souverain (données métier dans le navigateur, RGPD). IMPORTANT : Keystone n''est PAS un logiciel d''immobilier ni d''un métier unique — c''est un OS d''outils métier, généraliste et modulaire.');
