INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('2d601a37-774f-4500-a70e-63a3b317fa93', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Keystone OS — OS complet · 129€/mois', '{"statement":"Pour équiper toute votre activité — les applications se parlent entre elles. (Soit ~9 € par application) Les 14 applications, nouveautés comprises Elles communiquent entre elles — c''est tout l''intérêt 3 000 conversations IA incluses par mois Support prioritaire"}', 'Keystone OS — OS complet · 129€/mois
